    private static AwkGoldenCase ParagraphEofCase(string name, string[] arguments, string input, string output) =>
        AwkGoldenCaseBuilder.Create(name, arguments, [File("/data", input)])
            .WithStdOut(output)
            .WithEnvironment([new("LC_ALL", "C.UTF-8"), new("TZ", "UTC")]).Build();

    // Build repeated source stages only. Every row retains its independent oracle output.
    private static string ParagraphEofProgram(string read, string[] separators, bool detailed, string observed,
        string? closeTarget = null)
    {
        var program = new System.Text.StringBuilder(detailed
            ? "BEGIN{$0=\"seed fields\";v=\"kept\";i=0;ERRNO=\"keep\";"
            : "BEGIN{$0=\"seed fields\";v=\"kept\";ERRNO=\"keep\";");
        for (var index = 0; index < separators.Length; index++)
        {
            program.Append("stage=").Append((index + 1).ToString(System.Globalization.CultureInfo.InvariantCulture))
                .Append(";RS=\"").Append(separators[index]).Append("\";RT=\"X\";code=(").Append(read).Append(");")
                .Append(detailed ? "n=0;for(k in a)n++;print stage,code,i,n," : "print stage,code,")
                .Append("NR,FNR,NF,\"[\"$0\"]\",\"[\"").Append(observed)
                .Append("\"]\",\"[\"RT\"]\",ERRNO;");
            if (index == 2 && closeTarget is not null)
                program.Append("print \"close\",close(\"").Append(closeTarget).Append("\");");
        }
        return program.Append("exit}").ToString();
    }
